<?php
require_once __DIR__ . '/config.php'; require_login();if(!fams_current_type_allows('MAIFIP','view_reports')){http_response_code(403);exit('Your user type does not have permission for this action. Contact the Site Administrator if this access is required.');}
require_role(['admin','encoder','social_worker','manager']);
$readOnly = (current_user()['role']??'')==='manager';
$activeFacility=active_data_facility($pdo);
$activeFacilityInfo=facility_info($activeFacility);
$year=(int)($_GET['year']??date('Y')); $month=(int)($_GET['month']??date('n'));
if($year<2000 || $year>2100 || $month<1 || $month>12){http_response_code(400);exit('Invalid reporting period.');}
$monthNames=[1=>'January',2=>'February',3=>'March',4=>'April',5=>'May',6=>'June',7=>'July',8=>'August',9=>'September',10=>'October',11=>'November',12=>'December'];
$rows=maifip_monthly_released_records($pdo,$year,$month);
$fundReconciliation=maifip_monthly_fund_reconciliation($pdo,$year,$month);
$v=['amount'=>$fundReconciliation['disbursements'],'clients'=>$fundReconciliation['clients'],'source'=>$fundReconciliation['disbursement_source']];
$downloadedBalance=$fundReconciliation['fund_downloads'];
$adjustmentAmount=$fundReconciliation['adjustments'];
$openingBalance=$fundReconciliation['opening_balance'];
$openingBalanceLabel='NEW BALANCE — AS OF '.strtoupper($monthNames[$month]).' 1, '.$year;
$remaining=$fundReconciliation['ending_balance'];
$reportTitle='DISBURSED MEDICAL ASSISTANCE TO '.$activeFacilityInfo['short'].' - MONTH OF '.strtoupper($monthNames[$month]).' '.$year;
function sheet_name($r){return trim(preg_replace('/\s+/',' ',($r['patient_first_name']??'').' '.($r['patient_middle_name']??'').' '.($r['patient_last_name']??'').' '.($r['patient_name_extension']??'')));}
function sheet_address($r){$parts=array_filter([trim((string)$r['barangay']),trim((string)$r['municipality']),trim((string)$r['province'])]); return implode(', ',$parts);}
$data=[];
foreach($rows as $i=>$r){
    $data[]=[
        'no'=>$i+1,
        'date_submission'=>(string)$r['date_submission'],
        'patient_name'=>sheet_name($r),
        'address'=>sheet_address($r),
        'guarantee_amount'=>(float)$r['guarantee_amount'],
        'guardian'=>(string)($r['guardian']??''),
        'endorsed_by'=>'—',
        'approved_by'=>'—',
        'contact'=>(string)($r['contact_number']??''),
        'status'=>(string)$r['status'],
        'release_date'=>(string)($r['release_date']??''),
        'remarks'=>(string)($r['remarks']??'')
    ];
}
$payload=['year'=>$year,'month'=>$month,'monthName'=>$monthNames[$month],'summaryAmount'=>(float)$v['amount'],'summaryClients'=>(int)$v['clients'],'fund'=>$fund,'openingBalance'=>$openingBalance,'downloadedBalance'=>$downloadedBalance,'adjustmentAmount'=>$adjustmentAmount,'remaining'=>$remaining,'fundReconciliation'=>$fundReconciliation,'openingBalanceLabel'=>$openingBalanceLabel,'reportTitle'=>$reportTitle,'signatureNames'=>['staff'=>'MARY JANE C. MABAZZA','manager'=>'CRISTINA P. ASUNCION','representative'=>'HON. ALLAN U. TY'],'signatureDesignations'=>['staff'=>'LPGMA STAFF','manager'=>'LPGMA MANAGER','representative'=>'LPGMA REPRESENTATIVE'],'rows'=>$data];
log_action($pdo,'OPEN_MONTHLY_SHEET_EDITOR',"Opened editable {$year}-".sprintf('%02d',$month).' '.$activeFacilityInfo['short'].' monthly disbursement sheet.');
?>
