function esc(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));}
function num(v){const n=parseFloat(String(v??'').replace(/[^0-9.-]/g,''));return Number.isFinite(n)?n:0;} function money(v){return '₱'+num(v).toLocaleString('en-PH',{minimumFractionDigits:2,maximumFractionDigits:2});}
function getRows(){return [...body.querySelectorAll('tr:not(.deleted):not(.empty-row)')].map((tr,i)=>({
 no:i+1,date_submission:tr.querySelector('[data-field="date_submission"]').innerText.trim(),patient_name:tr.querySelector('[data-field="patient_name"]').innerText.trim(),address:tr.querySelector('[data-field="address"]').innerText.trim(),guarantee_amount:num(tr.querySelector('[data-field="guarantee_amount"]').innerText),guardian:tr.querySelector('[data-field="guardian"]').innerText.trim(),endorsed_by:tr.querySelector('[data-field="endorsed_by"]').innerText.trim(),approved_by:tr.querySelector('[data-field="approved_by"]').innerText.trim(),contact:tr.querySelector('[data-field="contact"]').innerText.trim(),status:tr.querySelector('[data-field="status"]').innerText.trim(),release_date:tr.querySelector('[data-field="release_date"]').innerText.trim(),remarks:tr.querySelector('[data-field="remarks"]').innerText.trim()}));}
function render(rows){body.innerHTML=''; if(!rows.length){body.innerHTML='<tr class="empty-row"><td colspan="13" class="empty">NO RELEASED RECORDS FOR THIS MONTH</td></tr>'; updateTotals(); return;} rows.forEach((r,i)=>{const tr=document.createElement('tr'); tr.innerHTML=`<td class="no"><span class="row-resizer" title="Drag to resize row"></span>${i+1}</td><td class="editable date" contenteditable="<?= $readOnly ? "false" : "true" ?>" data-field="date_submission">${esc(r.date_submission)}</td><td class="editable name" contenteditable="<?= $readOnly ? "false" : "true" ?>" data-field="patient_name">${esc(r.patient_name)}</td><td class="editable address" contenteditable="<?= $readOnly ? "false" : "true" ?>" data-field="address">${esc(r.address)}</td><td class="editable amount money" contenteditable="<?= $readOnly ? "false" : "true" ?>" data-field="guarantee_amount">${esc(num(r.guarantee_amount).toFixed(2))}</td><td class="editable guardian" contenteditable="<?= $readOnly ? "false" : "true" ?>" data-field="guardian">${esc(r.guardian)}</td><td class="editable endorse" contenteditable="<?= $readOnly ? "false" : "true" ?>" data-field="endorsed_by">${esc(r.endorsed_by)}</td><td class="editable approve" contenteditable="<?= $readOnly ? "false" : "true" ?>" data-field="approved_by">${esc(r.approved_by)}</td><td class="editable contact" contenteditable="<?= $readOnly ? "false" : "true" ?>" data-field="contact">${esc(r.contact)}</td><td class="editable status" contenteditable="<?= $readOnly ? "false" : "true" ?>" data-field="status">${esc(r.status)}</td><td class="editable release" contenteditable="<?= $readOnly ? "false" : "true" ?>" data-field="release_date">${esc(r.release_date)}</td><td class="editable remarks" contenteditable="<?= $readOnly ? "false" : "true" ?>" data-field="remarks">${esc(r.remarks||'')}</td><td class="row-actions"><button class="btn danger delete-row" type="button">Delete</button></td>`; body.appendChild(tr);}); bind(); bindColumnResize(); updateTotals();}
function bindColumnResize(){document.querySelectorAll('#sheetTable th .col-resizer').forEach(h=>{h.onmousedown=e=>{e.preventDefault();const th=h.parentElement,start=e.clientX,startW=th.offsetWidth;const move=ev=>{const w=Math.max(48,startW+ev.clientX-start);th.style.width=w+'px';document.querySelectorAll('#sheetTable tr').forEach(tr=>{if(tr.children[th.cellIndex])tr.children[th.cellIndex].style.width=w+'px';});};const up=()=>{document.removeEventListener('mousemove',move);document.removeEventListener('mouseup',up);save();};document.addEventListener('mousemove',move);document.addEventListener('mouseup',up);};});}
function bind(){document.querySelectorAll('.sheet-editable-heading,.summary-editable,.summary-value-editable,.sheet-note').forEach(c=>{c.addEventListener('input',save);}); body.querySelectorAll('.row-resizer').forEach(h=>{h.onmousedown=e=>{e.preventDefault();const tr=h.closest('tr'),start=e.clientY,startH=tr.offsetHeight;const move=ev=>{tr.style.height=Math.max(24,startH+ev.clientY-start)+'px'};const up=()=>{document.removeEventListener('mousemove',move);document.removeEventListener('mouseup',up);save()};document.addEventListener('mousemove',move);document.addEventListener('mouseup',up);};}); body.querySelectorAll('.editable').forEach(c=>{c.addEventListener('input',()=>{updateTotals();markDirty();}); c.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();c.blur();}});}); body.querySelectorAll('.delete-row').forEach(b=>b.addEventListener('click',()=>{b.closest('tr').classList.add('deleted'); updateTotals(); markDirty();}));}
function updateTotals(){const rows=getRows(); const summaryOnly=!rows.length&&!!body.querySelector('.empty-row'); const total=summaryOnly?(Number(DATA.summaryAmount)||0):rows.reduce((s,r)=>s+(Number(r.guarantee_amount)||0),0); const clientCount=summaryOnly?(Number(DATA.summaryClients)||0):rows.length; const dl=document.getElementById('downloadedBalance'); const downloaded=dl?num(dl.value):(Number(DATA.downloadedBalance)||0); const adjustment=(Number(DATA.adjustmentAmount)||0); const remaining=(Number(DATA.openingBalance)||0)+downloaded+adjustment-total; document.getElementById('editedTotal').textContent=money(total); document.getElementById('editedCount').textContent=clientCount+' client(s)'; document.getElementById('summaryAmount').textContent=money(total); document.getElementById('openingBalance').textContent=money(DATA.openingBalance); document.getElementById('remaining').textContent=money(remaining); document.getElementById('totalClients').textContent=clientCount.toLocaleString('en-PH'); rows.forEach((r,i)=>{const tr=body.querySelectorAll('tr:not(.deleted):not(.empty-row)')[i]; if(tr) tr.querySelector('.no').textContent=i+1;});}
function save(){if(READ_ONLY)return;localStorage.setItem(KEY,JSON.stringify(getRows())); const ui={}; document.querySelectorAll('.sheet-editable-heading,.summary-editable,.summary-value-editable,.sheet-note').forEach((el,i)=>ui[i]=el.innerText.trim()); localStorage.setItem(KEY+'.ui',JSON.stringify(ui)); saveSignatures();}
function saveSignatures(){if(READ_ONLY)return;const sig={names:{},designations:{}}; document.querySelectorAll('.editable-signature').forEach(el=>sig.names[el.dataset.signature]=el.innerText.trim());document.querySelectorAll('.editable-designation').forEach(el=>sig.designations[el.dataset.designation]=el.innerText.trim());localStorage.setItem(SIGNKEY,JSON.stringify(sig));}
function loadUI(){if(READ_ONLY)return;let ui={};try{ui=JSON.parse(localStorage.getItem(KEY+'.ui')||'{}')}catch(e){} document.querySelectorAll('.sheet-editable-heading,.summary-editable,.summary-value-editable,.sheet-note').forEach((el,i)=>{if(ui[i]!==undefined)el.textContent=ui[i];});}
function loadSignatures(){let sig={},defaults={};try{sig=JSON.parse(localStorage.getItem(SIGNKEY)||'{}')}catch(e){}try{defaults=JSON.parse(localStorage.getItem(SIGNDEFAULTKEY)||'{}')}catch(e){}document.querySelectorAll('.editable-signature').forEach(el=>{el.textContent=(sig.names?.[el.dataset.signature]??defaults.names?.[el.dataset.signature]??DATA.signatureNames[el.dataset.signature]??'').trim();if(!READ_ONLY)el.addEventListener('input',saveSignatures);});document.querySelectorAll('.editable-designation').forEach(el=>{el.textContent=(sig.designations?.[el.dataset.designation]??defaults.designations?.[el.dataset.designation]??DATA.signatureDesignations[el.dataset.designation]??'').trim();if(!READ_ONLY)el.addEventListener('input',saveSignatures);});}
async function saveDownloadedBalance(){const raw=prompt('Enter signed adjustment amount (negative or positive):');if(raw===null)return;const amount=Number(String(raw).replace(/,/g,''));if(!Number.isFinite(amount)||amount===0){show('Enter a valid non-zero adjustment.');return;}const reason=prompt('Reason for this fund adjustment (required):');if(!reason||!reason.trim()){show('An adjustment reason is required.');return;}try{const res=await fetch('monthly_report_settings.php',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify({csrf_token:DATA.csrf,year:DATA.year,month:DATA.month,adjustment_amount:amount,reason:reason.trim()})});const data=await res.json().catch(()=>({}));if(!res.ok||!data.ok)throw new Error(data.error||'Unable to save fund adjustment.');show('Adjustment recorded. Reload the report to refresh the balance.');}catch(e){show(e.message||'Unable to save fund adjustment.');}}
function markDirty(){document.title='* Editable <?=e($activeFacilityInfo['short'])?> Disbursement Sheet - '+DATA.monthName+' '+DATA.year; document.querySelector('.meta').classList.add('dirty'); document.querySelector('.meta').textContent='Unsaved local edits • '+DATA.monthName+' '+DATA.year; save();}
function show(msg){toast.textContent=msg;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),1800);}
let toolbarBusy=false;
function setToolbarBusy(busy,label=''){
 toolbarBusy=busy;
 const toolbar=document.querySelector('.toolbar');
 if(toolbar){toolbar.classList.toggle('is-busy',busy);toolbar.setAttribute('aria-busy',busy?'true':'false');}
 document.querySelectorAll('.toolbar .btn').forEach(btn=>{btn.setAttribute('aria-disabled',busy?'true':'false'); btn.classList.toggle('toolbar-pending',busy);});
 if(label) show(label);
}
function exportExcel(){
 if(toolbarBusy)return;
 setToolbarBusy(true,'Preparing Excel export…');
 try{
 save();
 const rows=getRows();
 const summaryOnly=!rows.length&&!!body.querySelector('.empty-row');
 const exportedTotal=summaryOnly?(Number(DATA.summaryAmount)||0):rows.reduce((a,r)=>a+Number(r.guarantee_amount||0),0);
 const exportedCount=summaryOnly?(Number(DATA.summaryClients)||0):rows.length;
 const exportedTotalLabel=summaryOnly?'REPORTED TOTAL (HISTORICAL SUMMARY)':'EDITED TOTAL';
 const escXml=v=>String(v??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
 const uiEls=[...document.querySelectorAll('.sheet-editable-heading,.summary-editable,.summary-value-editable,.sheet-note')];
 const note=(document.querySelector('.sheet-note')?.innerText||'').trim();
 const sig={},designation={}; document.querySelectorAll('.editable-signature').forEach(el=>sig[el.dataset.signature]=el.innerText.trim());document.querySelectorAll('.editable-designation').forEach(el=>designation[el.dataset.designation]=el.innerText.trim());
 const headers=['NO','DATE OF SUBMISSION','PATIENT NAME','ADDRESS','GUARANTEE AMOUNT','GUARDIAN','ENDORSED BY','APPROVED BY','CONTACT','STATUS','RELEASE DATE','REMARKS'];
 const moneyCell=v=>'<td class="money">'+Number(v||0).toFixed(2)+'</td>';
 const html='<!DOCTYPE html><html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel" xmlns="http://www.w3.org/TR/REC-html40"><head><meta charset="utf-8"><style>'+
 'body{font-family:Arial,sans-serif;font-size:10pt}h1{text-align:center;font-size:16pt}h2{text-align:center;font-size:11pt}table{border-collapse:collapse;width:100%}th{background:#082f63;color:#fff;font-weight:bold;border:1px solid #555;padding:5px}td{border:1px solid #777;padding:4px;vertical-align:top}.money{text-align:right;mso-number-format:"#,##0.00"}.text{mso-number-format:"\\@"}.summary td{background:#eaf2f9;font-weight:bold}.sig{width:33%;text-align:center;padding-top:35px;border:0}.sigline{border-top:1px solid #333;font-weight:bold;padding-top:4px}.note{font-style:italic;color:#52667d}</style></head><body>'+
 '<h1>'+escXml(document.querySelector('.report-header-top .org')?.innerText||'<?=e($activeFacilityInfo['short'])?> - <?=e($activeFacilityInfo['name'])?>')+'</h1>'+
 '<h2>'+escXml(document.querySelector('.report-header-top .center')?.innerText||'DISBURSED ASSISTANCE')+' — '+escXml(DATA.monthName.toUpperCase()+' '+DATA.year)+'</h2>'+
 '<table class="summary"><tr><td>NEW BALANCE</td><td>'+escXml(document.getElementById('openingBalance')?.innerText||'')+'</td><td>FUND DOWNLOADS</td><td>'+escXml(document.getElementById('downloadedBalanceText')?.innerText||'')+'</td><td>ADJUSTMENTS</td><td>'+escXml(document.getElementById('adjustmentAmount')?.innerText||'')+'</td><td>LESS: RELEASED</td><td>'+escXml(document.getElementById('summaryAmount')?.innerText||'')+'</td><td>REMAINING BALANCE</td><td>'+escXml(document.getElementById('remaining')?.innerText||'')+'</td><td>TOTAL CLIENTS</td><td>'+escXml(document.getElementById('totalClients')?.innerText||'')+'</td></tr></table>'+
 (DATA.fundReconciliation?.summary_discrepancy?'<p class="note"><b>HISTORICAL SUMMARY DIFFERENCE:</b> Saved summary '+Number(DATA.fundReconciliation.stored_summary_amount).toFixed(2)+' / '+DATA.fundReconciliation.stored_summary_clients+' clients; live RELEASED records '+Number(DATA.fundReconciliation.disbursements).toFixed(2)+' / '+DATA.fundReconciliation.clients+' clients. Live records are used.</p>':'')+'<br/>'+
 '<table><thead><tr>'+headers.map(h=>'<th>'+escXml(h)+'</th>').join('')+'</tr></thead><tbody>'+rows.map((r,i)=>'<tr><td>'+((i+1))+'</td><td>'+escXml(r.date_submission)+'</td><td>'+escXml(r.patient_name)+'</td><td>'+escXml(r.address)+'</td>'+moneyCell(r.guarantee_amount)+'<td>'+escXml(r.guardian)+'</td><td>'+escXml(r.endorsed_by)+'</td><td>'+escXml(r.approved_by)+'</td><td class="text">'+escXml(r.contact)+'</td><td>'+escXml(r.status)+'</td><td>'+escXml(r.release_date)+'</td><td>'+escXml(r.remarks)+'</td></tr>').join('')+'</tbody><tfoot><tr><th colspan="4">'+escXml(exportedTotalLabel)+'</th>'+moneyCell(exportedTotal)+'<th colspan="8">'+exportedCount+' client(s)</th></tr></tfoot></table><p class="note">'+escXml(note)+'</p><table><tr><td class="sig"><div class="sigline">'+escXml(sig.staff||'')+'</div>'+escXml(designation.staff||'')+'</td><td class="sig"><div class="sigline">'+escXml(sig.manager||'')+'</div>'+escXml(designation.manager||'')+'</td><td class="sig"><div class="sigline">'+escXml(sig.representative||'')+'</div>'+escXml(designation.representative||'')+'</td></tr></table></body></html>';
 const blob=new Blob([html],{type:'application/vnd.ms-excel;charset=utf-8'}); const a=document.createElement('a'); const stamp=DATA.year+'-'+String(DATA.month).padStart(2,'0'); a.href=URL.createObjectURL(blob); a.download='<?=e($activeFacilityInfo['short'])?>_Disbursement_'+stamp+'_Edited.xls'; document.body.appendChild(a); a.click(); setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove();},1000); show('Excel export created.');
 }catch(e){ console.error(e); show(e.message||'Excel export could not be created.'); }
 finally{ setTimeout(()=>setToolbarBusy(false),350); }
}
function printSheet(pdf=false){
 if(toolbarBusy)return;
 setToolbarBusy(true,pdf?'Opening PDF print dialog…':'Opening print dialog…');
 try{save(); document.title=(pdf?'<?=e($activeFacilityInfo['short'])?> Disbursement PDF - ':'<?=e($activeFacilityInfo['short'])?> Disbursement Report - ')+DATA.monthName+' '+DATA.year; window.print();}
 catch(e){console.error(e);show(e.message||'Print could not be opened.');}
 finally{setTimeout(()=>setToolbarBusy(false),700);}
}
let stored=null; if(!READ_ONLY){try{stored=JSON.parse(localStorage.getItem(KEY)||'null');}catch(e){}} render(Array.isArray(stored)?stored:DATA.rows); if(READ_ONLY){document.querySelectorAll('.editable,.sheet-note,.editable-signature').forEach(el=>el.contentEditable='false');document.querySelectorAll('.col-resizer,.row-resizer').forEach(el=>el.style.display='none');} bindColumnResize(); loadUI(); loadSignatures();

const toolbar=document.querySelector('.toolbar');
document.getElementById('toggleEdit')?.addEventListener('click',e=>{if(READ_ONLY)return;editingEnabled=!editingEnabled;e.currentTarget.textContent=editingEnabled?'Editing Enabled':'Enable Editing';e.currentTarget.setAttribute('aria-pressed',editingEnabled?'true':'false');document.querySelectorAll('#sheetTable .editable,.editable-signature,.editable-designation,.sheet-note').forEach(el=>el.contentEditable=editingEnabled?'true':'false');});
const addRow=()=>{
 if(READ_ONLY||!editingEnabled||toolbarBusy)return;
 if(body.querySelector('.empty-row')) body.innerHTML='';
 const rows=getRows();
 const tr=document.createElement('tr'); const n=rows.length+1;
 tr.innerHTML=`<td class="no"><span class="row-resizer" title="Drag to resize row"></span>${n}</td><td class="editable date" contenteditable="<?= $readOnly ? "false" : "true" ?>" data-field="date_submission"></td><td class="editable name" contenteditable="<?= $readOnly ? "false" : "true" ?>" data-field="patient_name"></td><td class="editable address" contenteditable="<?= $readOnly ? "false" : "true" ?>" data-field="address"></td><td class="editable amount money" contenteditable="<?= $readOnly ? "false" : "true" ?>" data-field="guarantee_amount">0.00</td><td class="editable guardian" contenteditable="<?= $readOnly ? "false" : "true" ?>" data-field="guardian"></td><td class="editable endorse" contenteditable="<?= $readOnly ? "false" : "true" ?>" data-field="endorsed_by">—</td><td class="editable approve" contenteditable="<?= $readOnly ? "false" : "true" ?>" data-field="approved_by">—</td><td class="editable contact" contenteditable="<?= $readOnly ? "false" : "true" ?>" data-field="contact"></td><td class="editable status" contenteditable="<?= $readOnly ? "false" : "true" ?>" data-field="status">RELEASED</td><td class="editable release" contenteditable="<?= $readOnly ? "false" : "true" ?>" data-field="release_date"></td><td class="editable remarks" contenteditable="<?= $readOnly ? "false" : "true" ?>" data-field="remarks"></td><td class="row-actions"><button class="btn danger delete-row" type="button">Delete</button></td>`;
 body.appendChild(tr); bind(); bindColumnResize(); updateTotals(); markDirty(); tr.querySelector('[data-field="patient_name"]').focus();
};
const resetSheet=()=>{if(READ_ONLY||toolbarBusy)return;if(confirm('Reset this report sheet to the database values?')){localStorage.removeItem(KEY);localStorage.removeItem(KEY+'.ui');localStorage.removeItem(SIGNKEY);render(DATA.rows);loadUI();loadSignatures();document.title='Editable <?=e($activeFacilityInfo['short'])?> Disbursement Sheet - '+DATA.monthName+' '+DATA.year;document.querySelector('.meta').classList.remove('dirty');document.querySelector('.meta').textContent=DATA.monthName+' '+DATA.year+' • Click any yellow cell to edit';show('Edits reset.');}};
const closeSheet=()=>{if(toolbarBusy)return; try{if(window.opener&&!window.opener.closed){window.close();return;}}catch(e){} if(history.length>1)history.back();else window.location.href='records.php';};
toolbar?.addEventListener('click',e=>{
 const btn=e.target.closest('button[data-sheet-action]'); if(!btn||toolbarBusy)return;
 e.preventDefault(); e.stopPropagation();
 const action=btn.dataset.sheetAction;
 if(action==='add')addRow(); else if(action==='reset')resetSheet(); else if(action==='print')printSheet(false); else if(action==='excel')exportExcel(); else if(action==='pdf')printSheet(true); else if(action==='close')closeSheet();
});
document.getElementById('saveSignDefaults')?.addEventListener('click',()=>{if(READ_ONLY)return;saveSignatures();const defaults={names:{},designations:{}};document.querySelectorAll('.editable-signature').forEach(el=>defaults.names[el.dataset.signature]=el.innerText.trim());document.querySelectorAll('.editable-designation').forEach(el=>defaults.designations[el.dataset.designation]=el.innerText.trim());try{localStorage.setItem(SIGNDEFAULTKEY,JSON.stringify(defaults));show('Signatory names and designations saved as defaults for this facility on this browser.');}catch(e){show('Unable to save signatory defaults in this browser.');}});
window.addEventListener('beforeprint',save);
</script></body></html>
